import os
import requests

def extract_text(payload, config=None):
    config = config or {}
    url = "https://api.cloud.google.com/vision/v1/documents:annotate"
    headers = {
        "Authorization": f"Bearer {os.environ['GOOGLE_API_KEY']}",
        "Content-Type": "application/json"
    }
    response = requests.post(url, headers=headers, json=payload)
    result = response.json()
    return result
